def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full horizontal and vertical divider lines.
    hr = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    vc = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
          and grid[0][c] != 0]
    sep = grid[hr[0]][0] if hr else grid[0][vc[0]]

    def regions(size, dividers):
        bounds = [-1] + dividers + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    rows = regions(h, hr)
    cols = regions(w, vc)

    # Find the non-marker block that provides the repeated shape.
    marker_shape = {(1, 1), (1, 2), (2, 1), (2, 2)}
    template = None
    for r0, r1 in rows:
        for c0, c1 in cols:
            coords = {(r-r0, c-c0) for r in range(r0, r1)
                      for c in range(c0, c1) if grid[r][c] != 0}
            if coords and coords != marker_shape:
                template = coords
                break
        if template is not None:
            break

    out = [[0] * w for _ in range(h)]
    for r in hr:
        for c in range(w):
            out[r][c] = sep
    for c in vc:
        for r in range(h):
            out[r][c] = sep

    for r0, r1 in rows:
        # The color marker in the first block determines this block row's color.
        colors = [grid[r][c] for r in range(r0, r1)
                  for c in range(cols[0][0], cols[0][1]) if grid[r][c] != 0]
        color = colors[0] if colors else 0
        for c0, c1 in cols:
            for dr, dc in template:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color

    return out
